package cursor

import (
	"bufio"
	"context"
	"encoding/json"
	"io"
	"strings"
	"testing"

	"github.com/chenhg5/cc-connect/core"
)

// newTestSession creates a cursorSession suitable for unit tests (no real CLI process).
func newTestSession(mode string) *cursorSession {
	ctx, cancel := context.WithCancel(context.Background())
	cs := &cursorSession{
		cmd:     "agent",
		workDir: "/tmp",
		mode:    mode,
		events:  make(chan core.Event, 16),
		ctx:     ctx,
		cancel:  cancel,
	}
	cs.alive.Store(true)
	return cs
}

// connectStdinPipe wires an in-memory pipe as the session's stdin and returns
// the reader end so tests can inspect what was written.
func connectStdinPipe(cs *cursorSession) io.Reader {
	r, w := io.Pipe()
	cs.stdinMu.Lock()
	cs.stdin = w
	cs.stdinMu.Unlock()
	return r
}

// readInteractionResponse reads one JSON line from the reader.
func readInteractionResponse(t *testing.T, r io.Reader) map[string]any {
	t.Helper()
	scanner := bufio.NewScanner(r)
	if !scanner.Scan() {
		t.Fatal("expected a line from stdin pipe, got none")
	}
	var out map[string]any
	if err := json.Unmarshal(scanner.Bytes(), &out); err != nil {
		t.Fatalf("parse stdin JSON: %v (line: %s)", err, scanner.Text())
	}
	return out
}

// webFetchInteractionRequest builds a raw map matching Cursor's interaction_query/request.
func webFetchInteractionRequest(id int, url string, skipApproval bool) map[string]any {
	return map[string]any{
		"type":       "interaction_query",
		"subtype":    "request",
		"query_type": "webFetchRequestQuery",
		"query": map[string]any{
			"id": float64(id),
			"webFetchRequestQuery": map[string]any{
				"args":         map[string]any{"url": url},
				"skipApproval": skipApproval,
			},
		},
	}
}

// shellInteractionRequest builds a raw map matching Cursor's shellRequestQuery.
func shellInteractionRequest(id int, cmd string, skipApproval bool) map[string]any {
	return map[string]any{
		"type":       "interaction_query",
		"subtype":    "request",
		"query_type": "shellRequestQuery",
		"query": map[string]any{
			"id": float64(id),
			"shellRequestQuery": map[string]any{
				"args":         map[string]any{"command": cmd},
				"skipApproval": skipApproval,
			},
		},
	}
}

// TestHandleInteractionQuery_DefaultMode_EmitsPermissionRequest checks that in
// default mode an interaction_query/request causes an EventPermissionRequest and
// no automatic stdin response (user must approve/deny via RespondPermission).
func TestHandleInteractionQuery_DefaultMode_EmitsPermissionRequest(t *testing.T) {
	cs := newTestSession("default")
	defer cs.cancel()
	_ = connectStdinPipe(cs)

	cs.handleInteractionQuery(webFetchInteractionRequest(0, "https://example.com", false))

	select {
	case evt := <-cs.events:
		if evt.Type != core.EventPermissionRequest {
			t.Fatalf("event type = %q, want EventPermissionRequest", evt.Type)
		}
		if evt.ToolName != "WebFetch" {
			t.Errorf("tool name = %q, want WebFetch", evt.ToolName)
		}
		if evt.ToolInput != "https://example.com" {
			t.Errorf("tool input = %q, want https://example.com", evt.ToolInput)
		}
		if evt.RequestID == "" {
			t.Error("request ID should be non-empty")
		}
	default:
		t.Fatal("expected EventPermissionRequest, got nothing")
	}
}

// TestHandleInteractionQuery_DefaultMode_ShellEmitsPermissionRequest checks the
// same for shellRequestQuery (the originally reported Windows bug scenario).
func TestHandleInteractionQuery_DefaultMode_ShellEmitsPermissionRequest(t *testing.T) {
	cs := newTestSession("default")
	defer cs.cancel()
	_ = connectStdinPipe(cs)

	cs.handleInteractionQuery(shellInteractionRequest(1, "git clone https://example.com", false))

	select {
	case evt := <-cs.events:
		if evt.Type != core.EventPermissionRequest {
			t.Fatalf("event type = %q, want EventPermissionRequest", evt.Type)
		}
		if evt.ToolName != "Bash" {
			t.Errorf("tool name = %q, want Bash", evt.ToolName)
		}
	default:
		t.Fatal("expected EventPermissionRequest for shell query, got nothing")
	}
}

// TestHandleInteractionQuery_SkipApproval_AutoApproves checks that when Cursor
// marks a request as skipApproval=true, we immediately write an approval response.
func TestHandleInteractionQuery_SkipApproval_AutoApproves(t *testing.T) {
	cs := newTestSession("default")
	defer cs.cancel()
	r := connectStdinPipe(cs)

	done := make(chan map[string]any, 1)
	go func() {
		done <- readInteractionResponse(t, r)
	}()

	cs.handleInteractionQuery(webFetchInteractionRequest(3, "https://example.com", true))

	resp := <-done
	if resp["subtype"] != "response" {
		t.Errorf("subtype = %q, want response", resp["subtype"])
	}
	response, _ := resp["response"].(map[string]any)
	inner, _ := response["webFetchRequestResponse"].(map[string]any)
	if _, ok := inner["approved"]; !ok {
		t.Errorf("expected approved in response, got %v", inner)
	}
}

// TestHandleInteractionQuery_NonDefaultMode_AutoDenies verifies that in plan/ask
// mode interaction queries are denied immediately without user intervention.
func TestHandleInteractionQuery_NonDefaultMode_AutoDenies(t *testing.T) {
	for _, mode := range []string{"plan", "ask"} {
		t.Run(mode, func(t *testing.T) {
			cs := newTestSession(mode)
			defer cs.cancel()
			r := connectStdinPipe(cs)

			done := make(chan map[string]any, 1)
			go func() {
				done <- readInteractionResponse(t, r)
			}()

			cs.handleInteractionQuery(webFetchInteractionRequest(0, "https://example.com", false))

			resp := <-done
			response, _ := resp["response"].(map[string]any)
			inner, _ := response["webFetchRequestResponse"].(map[string]any)
			if _, ok := inner["rejected"]; !ok {
				t.Errorf("mode=%s: expected rejected in response, got %v", mode, inner)
			}

			// No EventPermissionRequest should be emitted.
			select {
			case evt := <-cs.events:
				t.Errorf("mode=%s: unexpected event %q", mode, evt.Type)
			default:
			}
		})
	}
}

// TestRespondPermission_Approve writes an approval for a pending query and checks
// that the correct JSON is sent to stdin.
func TestRespondPermission_Approve(t *testing.T) {
	cs := newTestSession("default")
	defer cs.cancel()
	r := connectStdinPipe(cs)

	// Simulate a pending interaction query (as would be set by handleInteractionQuery).
	cs.pendingMu.Lock()
	cs.pending = &pendingInteractionQuery{id: 7, queryType: "webFetchRequestQuery"}
	cs.pendingMu.Unlock()

	done := make(chan map[string]any, 1)
	go func() {
		done <- readInteractionResponse(t, r)
	}()

	if err := cs.RespondPermission("webFetchRequestQuery:7", core.PermissionResult{Behavior: "allow"}); err != nil {
		t.Fatalf("RespondPermission: %v", err)
	}

	resp := <-done
	if resp["type"] != "interaction_query" {
		t.Errorf("type = %q, want interaction_query", resp["type"])
	}
	if resp["subtype"] != "response" {
		t.Errorf("subtype = %q, want response", resp["subtype"])
	}
	if resp["query_type"] != "webFetchRequestQuery" {
		t.Errorf("query_type = %q, want webFetchRequestQuery", resp["query_type"])
	}
	response, _ := resp["response"].(map[string]any)
	if idVal, _ := response["id"].(float64); int(idVal) != 7 {
		t.Errorf("response.id = %v, want 7", response["id"])
	}
	inner, _ := response["webFetchRequestResponse"].(map[string]any)
	if _, ok := inner["approved"]; !ok {
		t.Errorf("expected approved in response body, got %v", inner)
	}

	// Pending should be cleared.
	cs.pendingMu.Lock()
	pending := cs.pending
	cs.pendingMu.Unlock()
	if pending != nil {
		t.Error("pending query should be nil after RespondPermission")
	}
}

// TestRespondPermission_Deny verifies denial responses.
func TestRespondPermission_Deny(t *testing.T) {
	cs := newTestSession("default")
	defer cs.cancel()
	r := connectStdinPipe(cs)

	cs.pendingMu.Lock()
	cs.pending = &pendingInteractionQuery{id: 2, queryType: "shellRequestQuery"}
	cs.pendingMu.Unlock()

	done := make(chan map[string]any, 1)
	go func() {
		done <- readInteractionResponse(t, r)
	}()

	if err := cs.RespondPermission("shellRequestQuery:2", core.PermissionResult{
		Behavior: "deny",
		Message:  "user rejected",
	}); err != nil {
		t.Fatalf("RespondPermission: %v", err)
	}

	resp := <-done
	response, _ := resp["response"].(map[string]any)
	inner, _ := response["shellRequestResponse"].(map[string]any)
	rejected, _ := inner["rejected"].(map[string]any)
	if rejected["reason"] != "user rejected" {
		t.Errorf("reject reason = %q, want \"user rejected\"", rejected["reason"])
	}
}

// TestRespondPermission_NoPending is a no-op regression guard: if no query is
// pending (e.g. force mode or stale call), RespondPermission must not panic.
func TestRespondPermission_NoPending(t *testing.T) {
	cs := newTestSession("default")
	defer cs.cancel()

	if err := cs.RespondPermission("some-id", core.PermissionResult{Behavior: "allow"}); err != nil {
		t.Fatalf("RespondPermission with no pending: %v", err)
	}
}

// TestWriteInteractionResponse_ResponseFormat exercises the JSON shape emitted
// for both approval and denial paths.
func TestWriteInteractionResponse_ResponseFormat(t *testing.T) {
	cases := []struct {
		name      string
		queryType string
		approved  bool
		wantKey   string
	}{
		{"web-approve", "webFetchRequestQuery", true, "approved"},
		{"web-deny", "webFetchRequestQuery", false, "rejected"},
		{"shell-approve", "shellRequestQuery", true, "approved"},
		{"shell-deny", "shellRequestQuery", false, "rejected"},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			cs := newTestSession("default")
			defer cs.cancel()
			r := connectStdinPipe(cs)

			done := make(chan string, 1)
			go func() {
				scanner := bufio.NewScanner(r)
				if scanner.Scan() {
					done <- scanner.Text()
				}
			}()

			cs.writeInteractionResponse(0, tc.queryType, tc.approved, "test reason")

			line := <-done
			if !strings.Contains(line, tc.wantKey) {
				t.Errorf("response JSON does not contain %q: %s", tc.wantKey, line)
			}
		})
	}
}

package codex

import (
	"context"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
)

func TestAvailableModels_FallbackToModelsCache(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "forbidden", http.StatusForbidden)
	}))
	defer srv.Close()

	tmp := t.TempDir()
	cache := `{
  "models": [
    {"slug":"gpt-5.4","description":"Latest frontier agentic coding model.","visibility":"list","supported_in_api":true},
    {"slug":"gpt-5.3-codex","description":"Great for coding","visibility":"list","supported_in_api":true},
    {"slug":"hidden-internal","visibility":"hidden","supported_in_api":true},
    {"slug":"tool-only","visibility":"list","supported_in_api":false}
  ]
}`
	if err := os.WriteFile(tmp+"/models_cache.json", []byte(cache), 0o600); err != nil {
		t.Fatalf("write models_cache.json: %v", err)
	}

	t.Setenv("CODEX_HOME", tmp)
	t.Setenv("OPENAI_API_KEY", "test-key")
	t.Setenv("OPENAI_BASE_URL", srv.URL)

	a := &Agent{activeIdx: -1}
	models := a.AvailableModels(context.Background())
	if len(models) != 2 {
		t.Fatalf("models length = %d, want 2, models=%v", len(models), models)
	}
	if models[0].Name != "gpt-5.4" || models[1].Name != "gpt-5.3-codex" {
		t.Fatalf("models = %v, want [gpt-5.4 gpt-5.3-codex]", models)
	}
}

// TestAvailableModels_UsesModelCatalog tests that when CODEX_HOME/config.toml
// contains model_catalog_json, readCodexModelCatalog reads and parses that file
// as the highest-priority model source.
func TestAvailableModels_UsesModelCatalog(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "forbidden", http.StatusForbidden)
	}))
	defer srv.Close()

	tmp := t.TempDir()

	config := `model_catalog_json = "model_catalog.json"
`
	if err := os.WriteFile(tmp+"/config.toml", []byte(config), 0o644); err != nil {
		t.Fatalf("write config.toml: %v", err)
	}

	// Mix of models: list-visible API-supported, hidden, non-API, and
	// one with an empty slug that falls back to display_name.
	catalog := `{
  "models": [
    {"slug":"gpt-5.4","display_name":"GPT-5.4","description":"Latest frontier agentic coding model.","visibility":"list","supported_in_api":true},
    {"slug":"gpt-5.3-codex","display_name":"GPT-5.3 Codex","description":"Great for coding","visibility":"list","supported_in_api":true},
    {"slug":"hidden-internal","visibility":"hidden","supported_in_api":true},
    {"slug":"tool-only","visibility":"list","supported_in_api":false},
    {"slug":"","display_name":"MissingSlug","visibility":"list","supported_in_api":true}
  ]
}`
	if err := os.WriteFile(tmp+"/model_catalog.json", []byte(catalog), 0o644); err != nil {
		t.Fatalf("write model_catalog.json: %v", err)
	}

	t.Setenv("CODEX_HOME", tmp)
	t.Setenv("OPENAI_API_KEY", "test-key")
	t.Setenv("OPENAI_BASE_URL", srv.URL)

	a := &Agent{activeIdx: -1}
	models := a.AvailableModels(context.Background())

	// 3 visible+supported: gpt-5.4, gpt-5.3-codex, MissingSlug (slug empty → display_name fallback)
	if len(models) != 3 {
		t.Fatalf("models length = %d, want 3, models=%v", len(models), models)
	}
	if models[0].Name != "gpt-5.4" || models[0].Desc != "Latest frontier agentic coding model." {
		t.Errorf("models[0] = %+v, want gpt-5.4 with description", models[0])
	}
	if models[1].Name != "gpt-5.3-codex" || models[1].Desc != "Great for coding" {
		t.Errorf("models[1] = %+v, want gpt-5.3-codex with description", models[1])
	}
	if models[2].Name != "MissingSlug" || models[2].Desc != "" {
		t.Errorf("models[2] = %+v, want MissingSlug (display_name fallback)", models[2])
	}
}

// TestReadCodexModelCatalog_NoConfigFile tests graceful fallback when
// CODEX_HOME/config.toml does not exist.
func TestReadCodexModelCatalog_NoConfigFile(t *testing.T) {
	tmp := t.TempDir()
	t.Setenv("CODEX_HOME", tmp)

	a := &Agent{activeIdx: -1}
	models := a.AvailableModels(context.Background())

	// No config.toml → no model_catalog.json → no models_cache.json
	// → no OPENAI_API_KEY → all the way to hardcoded fallback (6 models)
	if len(models) != 6 {
		t.Fatalf("expected 6 hardcoded fallback models, got %d: %v", len(models), models)
	}
}

import api from './client';

export interface FeishuBeginResponse {
  device_code: string;
  qr_url: string;
  interval: number;
  expires_in: number;
}

export interface FeishuPollResponse {
  status: 'pending' | 'completed' | 'denied' | 'expired' | 'error';
  base_url?: string;
  app_id?: string;
  app_secret?: string;
  platform?: string;
  owner_open_id?: string;
  slow_down?: boolean;
  error?: string;
}

export interface WeixinBeginResponse {
  qr_key: string;
  qr_url: string;
}

export interface WeixinPollResponse {
  status: 'wait' | 'scaned' | 'confirmed' | 'expired';
  bot_token?: string;
  ilink_bot_id?: string;
  base_url?: string;
  ilink_user_id?: string;
}

export const setupFeishuBegin = () =>
  api.post<FeishuBeginResponse>('/setup/feishu/begin', {});

export const setupFeishuPoll = (deviceCode: string, baseUrl?: string) =>
  api.post<FeishuPollResponse>('/setup/feishu/poll', { device_code: deviceCode, base_url: baseUrl });

export const setupFeishuSave = (body: {
  project: string; app_id: string; app_secret: string; platform_type: string;
  owner_open_id?: string; work_dir?: string; agent_type?: string;
}) => api.post<{ message: string; restart_required: boolean }>('/setup/feishu/save', body);

export const setupWeixinBegin = (apiUrl?: string) =>
  api.post<WeixinBeginResponse>('/setup/weixin/begin', { api_url: apiUrl });

export const setupWeixinPoll = (qrKey: string, apiUrl?: string) =>
  api.post<WeixinPollResponse>('/setup/weixin/poll', { qr_key: qrKey, api_url: apiUrl });

export const setupWeixinSave = (body: {
  project: string; token: string; base_url?: string;
  ilink_bot_id?: string; ilink_user_id?: string; work_dir?: string; agent_type?: string;
}) => api.post<{ message: string; restart_required: boolean }>('/setup/weixin/save', body);

package core

import "testing"

func TestResolveModelAlias_CaseInsensitive(t *testing.T) {
	models := []ModelOption{{Name: "gpt-5.3-codex", Alias: "Codex"}}

	got := resolveModelAlias(models, "codex")
	if got != "gpt-5.3-codex" {
		t.Fatalf("resolveModelAlias() = %q, want %q", got, "gpt-5.3-codex")
	}
}

func TestResolveModelAlias_NoMatchFallsBackToInput(t *testing.T) {
	models := []ModelOption{{Name: "gpt-5.3-codex", Alias: "codex"}}

	got := resolveModelAlias(models, "gpt-5.4")
	if got != "gpt-5.4" {
		t.Fatalf("resolveModelAlias() = %q, want original input", got)
	}
}

func TestParseModelSwitchArgs(t *testing.T) {
	tests := []struct {
		name string
		args []string
		want string
		ok   bool
	}{
		{name: "legacy syntax", args: []string{"gpt"}, want: "gpt", ok: true},
		{name: "switch syntax", args: []string{"switch", "gpt"}, want: "gpt", ok: true},
		{name: "missing switch target", args: []string{"switch"}, ok: false},
		{name: "unknown subcommand", args: []string{"list", "gpt"}, ok: false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, ok := parseModelSwitchArgs(tt.args)
			if ok != tt.ok {
				t.Fatalf("parseModelSwitchArgs() ok = %v, want %v", ok, tt.ok)
			}
			if got != tt.want {
				t.Fatalf("parseModelSwitchArgs() = %q, want %q", got, tt.want)
			}
		})
	}
}

package core

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestHandleSend_AllowsAttachmentOnly(t *testing.T) {
	engine := NewEngine("test", &stubAgent{}, []Platform{&stubMediaPlatform{stubPlatformEngine: stubPlatformEngine{n: "test"}}}, "", LangEnglish)
	engine.interactiveStates["session-1"] = &interactiveState{
		platform: &stubMediaPlatform{stubPlatformEngine: stubPlatformEngine{n: "test"}},
		replyCtx: "reply-ctx",
	}

	api := &APIServer{engines: map[string]*Engine{"test": engine}}
	reqBody := SendRequest{
		Project:    "test",
		SessionKey: "session-1",
		Images: []ImageAttachment{{
			MimeType: "image/png",
			Data:     []byte("img"),
			FileName: "chart.png",
		}},
	}
	body, err := json.Marshal(reqBody)
	if err != nil {
		t.Fatalf("marshal request: %v", err)
	}

	req := httptest.NewRequest(http.MethodPost, "/send", bytes.NewReader(body))
	rec := httptest.NewRecorder()
	api.handleSend(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, body=%s", rec.Code, rec.Body.String())
	}
}

func TestHandleSend_AllowsTTSTextOnly(t *testing.T) {
	tts := &recordingTTS{}
	platform := &audioStubPlatform{stubPlatformEngine: stubPlatformEngine{n: "feishu"}}
	engine := NewEngine("test", &stubAgent{}, []Platform{platform}, "", LangEnglish)
	engine.SetTTSConfig(&TTSCfg{
		Enabled:  true,
		Provider: "minimax",
		Voice:    "voice-x",
		Speed:    0.98,
		TTS:      tts,
	})
	engine.interactiveStates["session-1"] = &interactiveState{
		platform: platform,
		replyCtx: "reply-ctx",
	}

	api := &APIServer{engines: map[string]*Engine{"test": engine}}
	body, err := json.Marshal(SendRequest{
		Project:    "test",
		SessionKey: "session-1",
		TTSText:    "hello voice",
	})
	if err != nil {
		t.Fatalf("marshal request: %v", err)
	}

	req := httptest.NewRequest(http.MethodPost, "/send", bytes.NewReader(body))
	rec := httptest.NewRecorder()
	api.handleSend(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, body=%s", rec.Code, rec.Body.String())
	}
	text, opts, calls := tts.snapshot()
	if calls != 1 {
		t.Fatalf("tts calls = %d, want 1", calls)
	}
	if text != "hello voice" {
		t.Fatalf("tts text = %q", text)
	}
	if opts.Voice != "voice-x" || opts.Speed != 0.98 {
		t.Fatalf("tts opts = %#v", opts)
	}
	if _, format, audioCalls := platform.audioSnapshot(); audioCalls != 1 || format != "mp3" {
		t.Fatalf("audio calls/format = %d/%q", audioCalls, format)
	}
}

// TestHandleSend_UnknownProjectReturns404 ensures the API does NOT silently
// fall back to the only registered engine when the caller named a different
// project. Previously a typo'd project name routed messages to whatever
// single engine happened to be loaded.
func TestHandleSend_UnknownProjectReturns404(t *testing.T) {
	engine := NewEngine("projectA", &stubAgent{}, []Platform{&stubMediaPlatform{stubPlatformEngine: stubPlatformEngine{n: "test"}}}, "", LangEnglish)
	engine.interactiveStates["session-1"] = &interactiveState{
		platform: &stubMediaPlatform{stubPlatformEngine: stubPlatformEngine{n: "test"}},
		replyCtx: "reply-ctx",
	}

	api := &APIServer{engines: map[string]*Engine{"projectA": engine}}
	body, err := json.Marshal(SendRequest{
		Project:    "projectB", // typo; does NOT match the loaded engine
		SessionKey: "session-1",
		Message:    "hi",
	})
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}

	req := httptest.NewRequest(http.MethodPost, "/send", bytes.NewReader(body))
	rec := httptest.NewRecorder()
	api.handleSend(rec, req)

	if rec.Code != http.StatusNotFound {
		t.Fatalf("status = %d, want 404; body=%s", rec.Code, rec.Body.String())
	}
	if !strings.Contains(rec.Body.String(), `"projectB"`) {
		t.Errorf("body should mention the unknown project name, got: %s", rec.Body.String())
	}
}

// TestHandleSend_EmptyProjectFallsBackToSingleEngine documents the intended
// convenience behavior: when the caller omits project entirely AND only one
// engine is loaded, the API picks it automatically.
func TestHandleSend_EmptyProjectFallsBackToSingleEngine(t *testing.T) {
	engine := NewEngine("solo", &stubAgent{}, []Platform{&stubMediaPlatform{stubPlatformEngine: stubPlatformEngine{n: "test"}}}, "", LangEnglish)
	engine.interactiveStates["session-1"] = &interactiveState{
		platform: &stubMediaPlatform{stubPlatformEngine: stubPlatformEngine{n: "test"}},
		replyCtx: "reply-ctx",
	}

