	"github.com/chenhg5/cc-connect/core"
)

func TestIFlowSessionIntegration(t *testing.T) {
	if os.Getenv("IFLOW_INTEGRATION") == "" {
		t.Skip("set IFLOW_INTEGRATION=1 to run")
	}
	if _, err := exec.LookPath("iflow"); err != nil {
		t.Skip("iflow CLI not found in PATH")
	}

	a, err := New(map[string]any{"work_dir": "/tmp"})
	if err != nil {
		t.Fatalf("New: %v", err)
	}

	sess, err := a.StartSession(context.Background(), "")
	if err != nil {
		t.Fatalf("StartSession: %v", err)
	}
	defer sess.Close()

	if err := sess.Send("Reply exactly READY", "", nil, nil); err != nil {
		t.Fatalf("Send #1: %v", err)
	}
	res1 := waitForResult(t, sess.Events())
	if !strings.Contains(strings.ToUpper(res1.Content), "READY") {
		t.Fatalf("unexpected first result: %q", res1.Content)
	}
	sid := sess.CurrentSessionID()
	if sid == "" {
		t.Fatal("expected session id after first send")
	}

	if err := sess.Send("Reply exactly RESUMED", "", nil, nil); err != nil {
		t.Fatalf("Send #2: %v", err)
	}
	res2 := waitForResult(t, sess.Events())
	if !strings.Contains(strings.ToUpper(res2.Content), "RESUMED") {
		t.Fatalf("unexpected second result: %q", res2.Content)
	}
	if sid2 := sess.CurrentSessionID(); sid2 != sid {
		t.Fatalf("session id changed: %q -> %q", sid, sid2)
	}

	resumed, err := a.StartSession(context.Background(), sid)
	if err != nil {
		t.Fatalf("StartSession resume: %v", err)
	}
	defer resumed.Close()
	if err := resumed.Send("Reply exactly CONTINUED", "", nil, nil); err != nil {
		t.Fatalf("Send resume: %v", err)
	}
	res3 := waitForResult(t, resumed.Events())
	if !strings.Contains(strings.ToUpper(res3.Content), "CONTINUED") {
		t.Fatalf("unexpected resumed result: %q", res3.Content)
	}
	if sid3 := resumed.CurrentSessionID(); sid3 != sid {
		t.Fatalf("resumed session id mismatch: want %q, got %q", sid, sid3)
	}
}

func waitForResult(t *testing.T, ch <-chan core.Event) core.Event {
	t.Helper()
	timeout := time.After(90 * time.Second)
	for {
		select {
		case ev, ok := <-ch:
			if !ok {
				t.Fatal("events channel closed")
			}
			switch ev.Type {
			case core.EventError:
				t.Fatalf("event error: %v", ev.Error)
			case core.EventResult:
				fmt.Printf("[RESULT] sid=%s content=%s\n", ev.SessionID, ev.Content)
				return ev
			}
		case <-timeout:
			t.Fatal("timeout waiting for result")
		}
	}
}

package codex

import (
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// TestIntegration_CodexProviderFlow verifies the full provider config flow:
// 1. ensureCodexProviderConfig writes correct config.toml
// 2. ensureCodexAuth writes correct auth.json
// 3. Codex CLI can authenticate and respond using the written config
//
// Requires: SHENGSUANYUN_API_KEY env var and `codex` CLI in PATH.
// Skip with: go test ./agent/codex/ -run TestIntegration -v
func TestIntegration_CodexProviderFlow(t *testing.T) {
	apiKey := os.Getenv("SHENGSUANYUN_API_KEY")
	if apiKey == "" {
		t.Skip("SHENGSUANYUN_API_KEY not set, skipping integration test")
	}
	if _, err := exec.LookPath("codex"); err != nil {
		t.Skip("codex CLI not in PATH, skipping integration test")
	}

	home := filepath.Join(t.TempDir(), ".codex")

	// Step 1: write config.toml via our function
	err := ensureCodexProviderConfig(home, "shengsuanyun-codex",
		"https://router.shengsuanyun.com/api/v1", "responses", nil)
	if err != nil {
		t.Fatalf("ensureCodexProviderConfig: %v", err)
	}

	// Verify config.toml content
	cfgData, err := os.ReadFile(filepath.Join(home, "config.toml"))
	if err != nil {
		t.Fatalf("read config.toml: %v", err)
	}
	cfgContent := string(cfgData)
	t.Logf("Generated config.toml:\n%s", cfgContent)

	for _, want := range []string{
		`[model_providers.shengsuanyun-codex]`,
		`base_url = "https://router.shengsuanyun.com/api/v1"`,
		`wire_api = "responses"`,
		`env_key = "OPENAI_API_KEY"`,
	} {
		if !strings.Contains(cfgContent, want) {
			t.Errorf("config.toml missing: %s", want)
		}
	}

	// Step 2: write auth.json via our function
	err = ensureCodexAuth(home, apiKey)
	if err != nil {
		t.Fatalf("ensureCodexAuth: %v", err)
	}

	// Verify auth.json content
	authData, err := os.ReadFile(filepath.Join(home, "auth.json"))
	if err != nil {
		t.Fatalf("read auth.json: %v", err)
	}
	var authMap map[string]any
	if err := json.Unmarshal(authData, &authMap); err != nil {
		t.Fatalf("parse auth.json: %v", err)
	}
	if authMap["auth_mode"] != "apikey" {
		t.Errorf("auth_mode = %v, want apikey", authMap["auth_mode"])
	}
	if authMap["OPENAI_API_KEY"] != apiKey {
		t.Errorf("OPENAI_API_KEY not set correctly in auth.json")
	}

	// Step 3: run codex exec with the generated config
	workDir := filepath.Join(t.TempDir(), "repo")
	os.MkdirAll(workDir, 0o755)
	gitInit := exec.Command("git", "init", "-q")
	gitInit.Dir = workDir
	if err := gitInit.Run(); err != nil {
		t.Fatalf("git init: %v", err)
	}

	cmd := exec.Command("codex", "exec",
		"--model", "openai/gpt-5.3-codex",
		"-c", `model_provider="shengsuanyun-codex"`,
		"-c", `openai_base_url="https://router.shengsuanyun.com/api/v1"`,
		"--sandbox", "workspace-write",
		"-c", `approval_policy="never"`,
	)
	cmd.Dir = workDir
	cmd.Env = append(os.Environ(),
		"CODEX_HOME="+home,
		"OPENAI_API_KEY="+apiKey,
	)
	cmd.Stdin = strings.NewReader("reply with exactly 'integration-ok' and nothing else")

	output, err := cmd.CombinedOutput()
	t.Logf("Codex output:\n%s", string(output))

	if err != nil {
		t.Fatalf("codex exec failed: %v\noutput: %s", err, output)
	}
	if !strings.Contains(string(output), "integration-ok") {
		t.Errorf("expected 'integration-ok' in output, got:\n%s", output)
	}
}

package copilot

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"testing"
	"time"
)

// TestMain intercepts test binary re-executions used as a fake copilot process.
// When CC_MOCK_COPILOT_MODE is set, we run the mock server instead of tests.
func TestMain(m *testing.M) {
	mode := os.Getenv("CC_MOCK_COPILOT_MODE")
	switch mode {
	case "list_sessions":
		runMockCopilot(handleListSessions)
		os.Exit(0)
	case "delete_session":
		runMockCopilot(handleDeleteSession)
		os.Exit(0)
	default:
		os.Exit(m.Run())
	}
}

// mockCopilotHandler is called for each incoming JSON-RPC request.
// It should write a framed JSON-RPC response to stdout.
type mockCopilotHandler func(method string, id json.RawMessage, params json.RawMessage, w *lspWriter)

// runMockCopilot reads Content-Length framed JSON-RPC messages from stdin,
// dispatches them to handler, and exits on EOF.
func runMockCopilot(handler mockCopilotHandler) {
	reader := newLSPReader(os.Stdin)
	writer := newLSPWriter(os.Stdout)

	for {
		body, err := reader.readMessage()
		if err != nil {
			if err == io.EOF {
				return
			}
			return
		}

		var probe struct {
			ID     json.RawMessage `json:"id"`
			Method string          `json:"method"`
		}
		if json.Unmarshal(body, &probe) != nil {
			continue
		}
		// Only handle requests (have ID), skip notifications
		if len(probe.ID) == 0 {
			continue
		}
		handler(probe.Method, probe.ID, body, writer)
	}
}

func writeResponse(w *lspWriter, id json.RawMessage, result any) {
	res, _ := json.Marshal(result)
	_ = w.writeMessage(map[string]any{
		"jsonrpc": "2.0",
		"id":      id,
		"result":  json.RawMessage(res),
	})
}

func writeError(w *lspWriter, id json.RawMessage, code int, msg string) {
	_ = w.writeMessage(map[string]any{
		"jsonrpc": "2.0",
		"id":      id,
		"error":   map[string]any{"code": code, "message": msg},
	})
}

// handleListSessions is the mock that responds to ping + session.list.
func handleListSessions(method string, id json.RawMessage, _ json.RawMessage, w *lspWriter) {
	switch method {
	case "ping":
		writeResponse(w, id, map[string]any{"pong": true})
	case "session.list":
		summary1 := "First session"
		summary2 := "Second session"
		writeResponse(w, id, map[string]any{
			"sessions": []map[string]any{
				{
					"sessionId":    "sess-001",
					"startTime":    time.Now().Format(time.RFC3339),
					"modifiedTime": time.Now().Format(time.RFC3339),
					"summary":      &summary1,
				},
				{
					"sessionId":    "sess-002",
					"startTime":    time.Now().Format(time.RFC3339),
					"modifiedTime": time.Now().Format(time.RFC3339),
					"summary":      &summary2,
				},
			},
		})
	default:
		writeError(w, id, -32601, fmt.Sprintf("method not found: %s", method))
	}
}

// handleDeleteSession is the mock that responds to ping + session.delete.
func handleDeleteSession(method string, id json.RawMessage, _ json.RawMessage, w *lspWriter) {
	switch method {
	case "ping":
		writeResponse(w, id, map[string]any{"pong": true})
	case "session.delete":
		writeResponse(w, id, map[string]any{"success": true})
	default:
		writeError(w, id, -32601, fmt.Sprintf("method not found: %s", method))
	}
}
